 h,w=10,10
 g=[[0 for _ in range(w)] for _ in range(h)]
 colors=rng.sample([1,2,3,4,5,6,7,8,9], rng.randint(2,4))
 for x in colors:
  r=rng.randrange(h); a=rng.randrange(w-3); b=a+rng.randrange(2,5)
  g[r][a]=x; g[r][b]=x
  if rng.random()<.5:
   rr=min(h-1,r+1)
   for c in (a+1,a+2):
    if c<w: g[rr][c]=x
 return g"}

